uv -= 0.5;
uv *= uAspect.xy;
vec2 tmp = uv;
float dist = 1;
float inten = 1;
float mask = 0;
ret1 = 0;
int anz = 4;
float n = 1;
uv = multiply(uv,mat2(_qa));
//uv +=.3*q1;
